const fileName = items[0].json.name;

// الكود بتاعك زي ما هو عشان يشيل الامتداد والمسافات
const cleanedName = fileName.replace(/\.[^/.]+$/, "").trim().replace(/\s+/g, "_");

return [{ json: { public_id: cleanedName } }];

